prompt --application/shared_components/plugins/template_component/amc_design_card
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(240618710270901524)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_DESIGN_CARD'
,p_display_name=>'Design Card'
,p_supported_component_types=>'PARTIAL:REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-DCard amc-DCard--#STYLE# {case STATE/}{when success/}amc-DCard--stateSuccess{when warning/}amc-DCard--stateWarning{when danger/}amc-DCard--stateDanger{when info/}amc-DCard--stateInfo{otherwise/}amc-DCard--stateNeutral{endcase/}">',
'  <article class="amc-DCard-card">',
'    {if ?IMAGE_URL/}<figure class="amc-DCard-media"><img class="amc-DCard-img" src="#IMAGE_URL#" width="640" height="360" alt="" loading="lazy"></figure>{endif/}',
'    {if ?ICON/}<span class="amc-DCard-icon" aria-hidden="true"><span class="amc-DCard-glyph fa #ICON#"></span></span>{endif/}',
'    <div class="amc-DCard-body">',
'      <div class="amc-DCard-top">{if ?EYEBROW/}<p class="amc-DCard-eyebrow">#EYEBROW#</p>{endif/}{if ?BADGE/}<span class="amc-DCard-badge"><span class="amc-DCard-badgeDot" aria-hidden="true"></span>#BADGE#</span>{endif/}</div>',
'      <h3 class="amc-DCard-title">{if ?LINK_URL/}<a class="amc-DCard-link" href="#LINK_URL#">#TITLE#</a>{else/}#TITLE#{endif/}</h3>',
'      {if ?DESCRIPTION/}<p class="amc-DCard-desc">#DESCRIPTION#</p>{endif/}',
'    </div>',
'    <div class="amc-DCard-foot">{if ?VALUE/}<p class="amc-DCard-figure">{if ?VALUE_LABEL/}<span class="amc-DCard-valueLabel">#VALUE_LABEL#</span>{endif/}<span class="amc-DCard-value">#VALUE#</span></p>{endif/}{if ?META/}<span class="amc-DCard-meta">#META#</span>{endif/}{if ?LINK_URL/}{if ?LINK_LABEL/}<span class="amc-DCard-cta" aria-hidden="true">#LINK_LABEL#<span class="amc-DCard-ctaIcon fa fa-arrow-right"></span></span>{endif/}{endif/}</div>',
'  </article>',
'</div>'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>'<ul class="amc-DCards amc-DCards--#STYLE#{case COLUMNS/}{when 2/} amc-DCards--cols2{when 3/} amc-DCards--cols3{when 4/} amc-DCards--cols4{otherwise/}{endcase/}">#APEX$ROWS#</ul>'
,p_report_row_template=>'<li class="amc-DCards-item">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-design-card.css'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Pick a Style, then map Title (required) and any of Eyebrow, Description, Icon, Image URL, Badge, State, Value, Value Label, Meta, Link URL and Link Label to columns or static text. Empty settings are simply left out. The whole card becomes clickable when Link URL is set. Colors follow the active Universal Theme style, including dark styles and Theme Roller changes.'
,p_version_identifier=>'1.0.0'
,p_files_version=>1
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(465607393004745073)
,p_plugin_id=>wwv_flow_imp.id(240618710270901524)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'elevated'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Card design. Elevated: soft shadow, no border. Outline: hairline border, no shadow. Glass: translucent frosted surface. Gradient Border: gradient frame in the theme primary color. Image Top: picture above the text. Image Overlay: text on top of the picture. Horizontal: picture or icon beside the text. Accent Top: thick top edge in the State color. Ticket: main part plus a perforated stub for Value. Stacked Paper: sheets peeking out behind the card. Soft Inset: recessed surface. Corner Icon: large icon in the top corner.'
);
